<style>
.tea-ui{background:#f5f8fc;padding:0 0 24px}.tea-shell{padding:0 22px 24px}.tea-hero{background:linear-gradient(135deg,#fff,#f2fff7);border:1px solid #d8eadf;border-radius:18px;padding:22px 26px;margin-bottom:16px;box-shadow:0 12px 30px rgba(15,23,42,.08);border-left:6px solid #168a4b}.tea-eyebrow{font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#168a4b}.tea-hero h1{margin:4px 0 0;font-size:28px;font-weight:800;color:#102033}.tea-hero p{margin:7px 0 0;color:#64748b}.tea-nav{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 16px}.tea-nav a{padding:8px 12px;border-radius:9px;background:#fff;border:1px solid #dbe5ef;color:#334155;font-weight:700}.tea-nav a.active{background:#168a4b;color:#fff;border-color:#168a4b}.tea-card{background:#fff;border:1px solid #dbe5ef;border-radius:14px;margin-bottom:18px;box-shadow:0 8px 22px rgba(15,23,42,.06)}.tea-card-h{padding:14px 17px;border-bottom:1px solid #e5edf4;font-size:16px;font-weight:800;color:#17324d}.tea-card-b{padding:16px}.tea-grid{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:14px}.tea-kpi{background:#fff;border:1px solid #dbe5ef;border-radius:14px;padding:16px}.tea-kpi b{display:block;font-size:25px;color:#12263a}.tea-kpi span{color:#64748b;font-size:12px}.tea-form{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:12px}.tea-form .wide{grid-column:span 2}.tea-form label{display:block;font-size:12px;font-weight:800;color:#475569}.tea-form input,.tea-form select,.tea-form textarea{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:8px}.tea-table{width:100%;font-size:12px}.tea-table th{background:#eef5f0;font-weight:800}.tea-table th,.tea-table td{padding:8px;border-bottom:1px solid #e6edf3;vertical-align:top}.tea-scroll{overflow:auto}.tea-note{font-size:12px;color:#64748b}.tea-status{display:inline-block;padding:3px 8px;border-radius:999px;background:#eef2ff;font-weight:700;font-size:11px}.tea-actions{margin-top:12px}.tea-btn{display:inline-block;border:0;border-radius:8px;padding:8px 12px;font-weight:700;background:#168a4b;color:#fff}.tea-btn.secondary{background:#475569}.tea-btn.warn{background:#b7791f}@media(max-width:1000px){.tea-grid,.tea-form{grid-template-columns:repeat(2,minmax(150px,1fr))}}@media(max-width:640px){.tea-grid,.tea-form{grid-template-columns:1fr}.tea-form .wide{grid-column:span 1}.tea-shell{padding:0 10px}}
</style>
